package main

// Authored local bundle control. This is not an upstream reference solution.
import (
 "archive/zip"
 "bytes"
 "fmt"
 "io"
 "io/fs"
 "os"
 "path/filepath"
 "sort"
 "strings"
)

const portableBundleMethod = zip.Store

type portableBundleEntry struct { name string; mode fs.FileMode; data []byte }

func init() {
 if len(os.Args)<2 || os.Args[1]!="bundle" { return }
 if err:=portableBundleCommand(os.Args[2:]);err!=nil { fmt.Fprintln(os.Stderr,err);os.Exit(1) }
 os.Exit(0)
}

func portableBundleCommand(args []string) error {
 if len(args)==3 && args[0]=="create" { return portableBundleCreate(args[1],args[2]) }
 if len(args)==2 && args[0]=="verify" { _,err:=portableBundleRead(args[1]);return err }
 if len(args)==3 && args[0]=="extract" { return portableBundleExtract(args[1],args[2]) }
 return fmt.Errorf("usage: bundle create SOURCE ARCHIVE | verify ARCHIVE | extract ARCHIVE DEST")
}

func portableBundleCreate(source,destination string) (err error) {
 var entries []portableBundleEntry
 err=filepath.WalkDir(source,func(path string,d fs.DirEntry,walkErr error) error {
  if walkErr!=nil {return walkErr};if d.IsDir(){return nil}
  info,e:=d.Info();if e!=nil{return e};if !info.Mode().IsRegular(){return fmt.Errorf("nonregular bundle input")}
  relative,e:=filepath.Rel(source,path);if e!=nil{return e};data,e:=os.ReadFile(path);if e!=nil{return e}
  entries=append(entries,portableBundleEntry{filepath.ToSlash(relative),info.Mode().Perm(),data});return nil
 })
 if err!=nil{return err}
 sort.Slice(entries,func(i,j int)bool{return entries[i].name<entries[j].name})
 var buffer bytes.Buffer;writer:=zip.NewWriter(&buffer)
 for _,entry:=range entries {
  header:=&zip.FileHeader{Name:entry.name,Method:portableBundleMethod};header.SetMode(entry.mode)
  file,e:=writer.CreateHeader(header);if e!=nil{return e};if _,e=file.Write(entry.data);e!=nil{return e}
 }
 if err=writer.Close();err!=nil{return err}
 file,err:=os.OpenFile(destination,os.O_WRONLY|os.O_CREATE|os.O_EXCL,0600);if err!=nil{return err}
 defer func(){closeErr:=file.Close();if err==nil{err=closeErr};if err!=nil{os.Remove(destination)}}()
 _,err=file.Write(buffer.Bytes());return err
}

func portableBundleRead(path string) ([]portableBundleEntry,error) {
 reader,err:=zip.OpenReader(path);if err!=nil{return nil,err};defer reader.Close()
 entries:=make([]portableBundleEntry,0,len(reader.File));seen:=map[string]bool{}
 for _,file:=range reader.File {
  name:=file.Name
  if !filepath.IsLocal(filepath.FromSlash(name)) || strings.Contains(name,"\\") || filepath.ToSlash(filepath.Clean(name))!=name || !file.Mode().IsRegular() || seen[name] {return nil,fmt.Errorf("unsafe bundle member %q",name)}
  seen[name]=true;input,e:=file.Open();if e!=nil{return nil,e};data,e:=io.ReadAll(input);closeErr:=input.Close();if e!=nil{return nil,e};if closeErr!=nil{return nil,closeErr}
  entries=append(entries,portableBundleEntry{name,file.Mode().Perm(),data})
 }
 return entries,nil
}

func portableBundleExtract(archive,destination string) (err error) {
 entries,err:=portableBundleRead(archive);if err!=nil{return err}
 if _,err=os.Lstat(destination);err==nil{return fmt.Errorf("destination already exists")}else if !os.IsNotExist(err){return err}
 if err=os.Mkdir(destination,0755);err!=nil{return err}
 defer func(){if err!=nil{os.RemoveAll(destination)}}()
 for _,entry:=range entries {
  target:=filepath.Join(destination,filepath.FromSlash(entry.name))
  if err=os.MkdirAll(filepath.Dir(target),0755);err!=nil{return err}
  file,e:=os.OpenFile(target,os.O_WRONLY|os.O_CREATE|os.O_EXCL,entry.mode);if e!=nil{return e}
  _,writeErr:=file.Write(entry.data);closeErr:=file.Close();if writeErr!=nil{return writeErr};if closeErr!=nil{return closeErr}
  if err=os.Chmod(target,entry.mode);err!=nil{return err}
 }
 return nil
}

package main

import (
 "archive/zip"
 "bytes"
 "os"
 "path/filepath"
 "testing"
)

func TestPortableBundleRoundTrip(t *testing.T) {
 root:=t.TempDir();source:=filepath.Join(root,"source");if e:=os.Mkdir(source,0755);e!=nil{t.Fatal(e)}
 if e:=os.WriteFile(filepath.Join(source,"SKILL.md"),[]byte("body\n"),0644);e!=nil{t.Fatal(e)}
 if e:=os.WriteFile(filepath.Join(source,"check.sh"),[]byte("#!/bin/sh\nprintf checked\n"),0755);e!=nil{t.Fatal(e)}
 first,second:=filepath.Join(root,"first.zip"),filepath.Join(root,"second.zip")
 if e:=portableBundleCreate(source,first);e!=nil{t.Fatal(e)};if e:=portableBundleCreate(source,second);e!=nil{t.Fatal(e)}
 a,_:=os.ReadFile(first);b,_:=os.ReadFile(second);if !bytes.Equal(a,b){t.Fatal("not reproducible")}
 destination:=filepath.Join(root,"output");if e:=portableBundleExtract(first,destination);e!=nil{t.Fatal(e)}
 data,e:=os.ReadFile(filepath.Join(destination,"SKILL.md"));if e!=nil || string(data)!="body\n"{t.Fatalf("roundtrip %q %v",data,e)}
 info,e:=os.Stat(filepath.Join(destination,"check.sh"));if e!=nil || info.Mode().Perm()&0111==0{t.Fatal("executable mode lost")}
 if e:=portableBundleCreate(source,first);e==nil{t.Fatal("archive overwritten")}
 if e:=portableBundleExtract(first,destination);e==nil{t.Fatal("destination overwritten")}
}

func TestPortableBundleRejectsUnsafeAndCorrupt(t *testing.T) {
 root:=t.TempDir();archive:=filepath.Join(root,"unsafe.zip");var buffer bytes.Buffer;writer:=zip.NewWriter(&buffer)
 file,e:=writer.Create("../escape");if e!=nil{t.Fatal(e)};if _,e=file.Write([]byte("escape"));e!=nil{t.Fatal(e)};if e:=writer.Close();e!=nil{t.Fatal(e)}
 if e:=os.WriteFile(archive,buffer.Bytes(),0600);e!=nil{t.Fatal(e)}
 if _,e:=portableBundleRead(archive);e==nil{t.Fatal("unsafe archive accepted")}
 if e:=portableBundleExtract(archive,filepath.Join(root,"out"));e==nil{t.Fatal("unsafe extraction accepted")}
 if e:=os.WriteFile(archive,[]byte("not an archive"),0600);e!=nil{t.Fatal(e)}
 if _,e:=portableBundleRead(archive);e==nil{t.Fatal("corrupt archive accepted")}
}

